messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 400;
    const FINISH_LINE_Z = 0;
    const START_LINE_Z = 200;
    const RACE_DURATION = 8.0; // seconds per loop
    const LOOP_PAUSE = 2.0; // seconds pause before reset

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 50, 250);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 500);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(50, 100, 50);
    dirLight.castShadow = true;
    dirLight.shadow.camera.left = -50;
    dirLight.shadow.camera.right = 50;
    dirLight.shadow.camera.top = 50;
    dirLight.shadow.camera.bottom = -50;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    scene.add(dirLight);

    // --- Environment ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(1000, 1000);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Forest Green
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Track
    const trackWidth = 30;
    const trackGeo = new THREE.PlaneGeometry(trackWidth, 1000);
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.rotation.x = -Math.PI / 2;
    track.receiveShadow = true;
    scene.add(track);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(trackWidth, 4);
    // Checkerboard pattern using canvas texture
    const canvas = document.createElement('canvas');
    canvas.width = 64; canvas.height = 64;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = 'white'; ctx.fillRect(0,0,64,64);
    ctx.fillStyle = 'black'; ctx.fillRect(0,0,32,32); ctx.fillRect(32,32,32,32);
    const checkTex = new THREE.CanvasTexture(canvas);
    checkTex.magFilter = THREE.NearestFilter;

    const finishMat = new THREE.MeshStandardMaterial({ map: checkTex });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.05, FINISH_LINE_Z);
    scene.add(finishLine);

    // Finish Banner
    const bannerGeo = new THREE.BoxGeometry(trackWidth + 2, 1, 1);
    const bannerMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const banner = new THREE.Mesh(bannerGeo, bannerMat);
    banner.position.set(0, 8, FINISH_LINE_Z);
    scene.add(banner);

    const poleGeo = new THREE.CylinderGeometry(0.5, 0.5, 8);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
    const poleL = new THREE.Mesh(poleGeo, poleMat);
    poleL.position.set(-trackWidth/2 - 1, 4, FINISH_LINE_Z);
    scene.add(poleL);
    const poleR = new THREE.Mesh(poleGeo, poleMat);
    poleR.position.set(trackWidth/2 + 1, 4, FINISH_LINE_Z);
    scene.add(poleR);

    // --- Car Construction ---
    function createCar(colorHex) {
        const carGroup = new THREE.Group();

        // Body
        const bodyGeo = new THREE.BoxGeometry(2, 1, 4.5);
        const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = 0.75;
        body.castShadow = true;
        carGroup.add(body);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Dark windows
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.55;
        cabin.position.z = -0.2;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        const positions = [
            { x: -1.1, z: 1.5 }, { x: 1.1, z: 1.5 },
            { x: -1.1, z: -1.5 }, { x: 1.1, z: -1.5 }
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(pos.x, 0.4, pos.z);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        // Spoiler
        const spoilerGeo = new THREE.BoxGeometry(2.2, 0.1, 0.8);
        const spoiler = new THREE.Mesh(spoilerGeo, bodyMat);
        spoiler.position.set(0, 1.2, 2.2);
        carGroup.add(spoiler);

        const spoilerStandGeo = new THREE.BoxGeometry(0.1, 0.4, 0.1);
        const standL = new THREE.Mesh(spoilerStandGeo, new THREE.MeshStandardMaterial({color:0x000000}));
        standL.position.set(-0.8, 1.0, 2.2);
        carGroup.add(standL);
        const standR = new THREE.Mesh(spoilerStandGeo, new THREE.MeshStandardMaterial({color:0x000000}));
        standR.position.set(0.8, 1.0, 2.2);
        carGroup.add(standR);

        return carGroup;
    }

    const blueCar = createCar(0x0000FF); // Bright Blue
    const redCar = createCar(0xFF0000);  // Bright Red

    scene.add(blueCar);
    scene.add(redCar);

    // --- Animation Logic ---
    let raceTime = 0;
    let isPaused = false;
    let pauseTimer = 0;

    // Helper to calculate position based on time and easing
    // Returns Z position (0 is finish, positive is start)
    function getPosition(t, delay, speedFactor) {
        // t is 0 to 1
        // delay: start slightly later?
        // speedFactor: relative speed

        // Simple easing function: easeInCubic for acceleration
        let localT = Math.max(0, (t - 0.05) / (0.95 * speedFactor)); // Normalize time with delay and speed
        localT = Math.min(localT, 1);

        // Easing
        const ease = localT * localT * localT;

        // Map 0..1 to START_LINE_Z..FINISH_LINE_Z
        // START is 200, FINISH is 0.
        return START_LINE_Z - (ease * START_LINE_Z);
    }

    function animate() {
        requestAnimationFrame(animate);

        const delta = 0.016; // Approx 60fps step
        raceTime += delta;

        if (raceTime > RACE_DURATION) {
            isPaused = true;
            pauseTimer += delta;
        }

        if (isPaused) {
            if (pauseTimer > LOOP_PAUSE) {
                // Reset
                raceTime = 0;
                isPaused = false;
                pauseTimer = 0;
            }
        }

        // Calculate progress (0 to 1)
        let progress = raceTime / RACE_DURATION;
        if (isPaused) progress = 1; // Keep them at finish line

        // --- Car Logic ---
        // Blue Car: Starts fast, finishes slower
        // Red Car: Starts slower, finishes faster

        // We use a custom curve logic to ensure Red overtakes Blue
        // Blue: Linear-ish but slows down slightly at end
        // Red: Accelerates hard at end

        // Blue Car Z
        // Let's use a sine wave for natural movement variation
        // Blue is ahead early: position is lower Z
        let blueZ = START_LINE_Z - (Math.pow(progress, 0.9) * START_LINE_Z);

        // Red Car Z
        // Red is behind early (higher Z), overtakes (lower Z)
        // Red starts with a delay effectively
        let redProgress = Math.pow(progress, 1.3); // Cubic ease in, starts slow
        let redZ = START_LINE_Z - (redProgress * START_LINE_Z);

        // Ensure they don't go past finish line visually before reset
        if (blueZ < FINISH_LINE_Z) blueZ = FINISH_LINE_Z;
        if (redZ < FINISH_LINE_Z) redZ = FINISH_LINE_Z;

        // Update Positions
        blueCar.position.set(0, 0, blueZ);
        redCar.position.set(0, 0, redZ);

        // --- Camera Logic ---
        // Camera follows the average position of the two cars
        // But keeps a safe distance so both are visible

        const avgZ = (blueZ + redZ) / 2;
        const distZ = Math.abs(blueZ - redZ);

        // Camera follows behind the cars (positive Z)
        // As cars approach 0 (finish), camera moves to 0
        // Camera height and offset

        // We want the camera to be behind the trailing car, looking at the leading car
        const trailingZ = Math.max(blueZ, redZ);
        const leadingZ = Math.min(blueZ, redZ);

        // Camera target position
        // Start at Z=220, End at Z=20 (behind finish line)
        // We want to keep the finish line in view eventually

        let camZ = trailingZ + 30;
        let camY = 12;
        let camX = 0; // Slightly offset to see both lanes if we had lanes, but here they are stacked or close. 
                     // Let's offset X slightly to see the track width better.
        camX = 15; 

        // Smooth camera movement
        camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.1);

        // Look at the middle of the cars, slightly ahead
        const lookTarget = new THREE.Vector3(0, 2, avgZ - 10);
        camera.lookAt(lookTarget);

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();

</script>
</body>
</html>
```
